insert into public.page_sections (
  page_key, section_key, content, image, image_media_id, image_alt_text
)
values (
  'terms',
  'content',
  $json${"eyebrow": "LEGAL & TRUST", "title": "Terms and Conditions", "intro": "These Terms and Conditions apply to the ArtNovaX website, online community, future digital products, workshops, art-based activities, community events, educational programmes and research initiatives.", "updatedLabel": "Effective date: 12/10/2026 · Last reviewed: 12/10/2026", "sections": [{"title": "About ArtNovaX", "body": "ArtNovaX is a mental wellness initiative that uses art, creative expression, community engagement, education, technology and research to promote mental well-being.\n\nLegal entity: ArtNovaX Mental Health Foundation\nOfficial contact: info@artnovax.org\nLocation: Nairobi, Kenya"}, {"title": "Acceptance of the Terms", "body": "By accessing our website or digital platforms, registering for an event or participating in an activity, you agree to the terms applicable to that service.\n\nWhere separate permission is required for research, collection of sensitive personal data, photographs, recordings or promotional content, ArtNovaX will seek that permission separately.\n\nAcceptance of these Terms does not automatically mean that you consent to research participation, marketing communications, publication of your image or any optional use of your personal information."}, {"title": "Eligibility and Participation", "body": "ArtNovaX activities may be available to young adults aged 18–30.\n\nArtNovaX may restrict or discontinue participation where reasonably necessary to protect a participant or another person, address misconduct or meet legal and safeguarding obligations."}, {"title": "Nature of Our Activities", "body": "ArtNovaX provides creative activities, mental health education, community engagement and, where applicable, research.\n\nUnless expressly stated otherwise, our workshops and art-based activities are not a substitute for professional medical diagnosis, psychological treatment, psychiatric care or emergency services.\n\nParticipation does not guarantee a particular mental health outcome. Participants should seek qualified professional support where appropriate.\n\nAny future technology product will be subject to additional service-specific terms where necessary."}, {"title": "Participant Conduct and Community Standards", "body": "Participants must:\n\n• Treat others with dignity and respect.\n• Refrain from harassment, discrimination, intimidation and abusive conduct.\n• Respect other participants’ privacy and personal boundaries.\n• Obtain appropriate permission before recording, photographing or sharing another participant’s contributions.\n• Avoid sharing personal disclosures made by other participants outside the activity.\n• Follow reasonable safety and safeguarding instructions.\n\nArtNovaX may moderate online discussions, remove inappropriate content or suspend participation where necessary to maintain a safe and respectful environment.\n\nParticipants should not use ArtNovaX platforms to impersonate others, harass users, disclose another person’s private information or distribute unlawful or harmful content."}, {"title": "Privacy and Personal Data Protection", "body": "ArtNovaX aims to process personal data in accordance with Kenya’s Data Protection Act, 2019, applicable regulations and other relevant laws.\n\nWe may collect basic personal information and, for specific activities, sensitive personal data such as mental health information.\n\nThe details of what we collect, why we collect it, the applicable lawful basis, who may receive it, how long we retain it and how individuals can exercise their rights are set out in our Privacy Notice.\n\nParticipants should read the Privacy Notice before submitting personal information."}, {"title": "Research and Surveys", "body": "Participation in research is voluntary unless a particular study lawfully provides otherwise and clearly explains the applicable arrangement.\n\nBefore collecting research data, ArtNovaX will provide appropriate study information explaining the research purpose, procedures, foreseeable risks, expected benefits, data-handling arrangements, confidentiality limits and withdrawal arrangements.\n\nResearch participation is not a condition for attending unrelated community activities unless a clearly explained programme is specifically designed as a research study.\n\nArtNovaX will obtain any ethics approvals, research licences or other authorisations required for the particular study before commencing activities that require them."}, {"title": "Photography, Recordings and Creative Work", "body": "ArtNovaX may document activities for reporting, education, research or promotional purposes.\n\nParticipation in an event does not automatically grant ArtNovaX permission to publish an identifiable participant’s image, voice, personal story or artwork.\n\nWhere required, we will request separate permission identifying the intended purpose, channels of publication and relevant conditions. Additional safeguards will apply when children are involved.\n\nParticipants generally retain ownership of their original artwork and creative contributions. Any permission for ArtNovaX to reproduce, publish or otherwise use that work must be separately agreed where required."}, {"title": "Intellectual Property", "body": "ArtNovaX’s original branding, logo, website content and programme materials may not be reproduced or commercially exploited without permission, except where permitted by law.\n\nParticipants retain ownership of their original creative work unless a separate agreement provides otherwise.\n\nNo general licence to publish or commercially exploit participant work is created merely by attending an ArtNovaX event or uploading content to a platform."}, {"title": "Online Community and Future Technology", "body": "Where ArtNovaX provides online community features or a technology product, participants must use the service responsibly and comply with any additional platform rules.\n\nUsers should not share information about another person without appropriate authority or permission.\n\nOnline discussions are not automatically confidential or equivalent to a private consultation with a qualified mental health professional. ArtNovaX will explain the actual privacy arrangements and limitations of any service.\n\nAny future features involving automated assessments, profiling, personalised recommendations or other processing that could significantly affect individuals will require an appropriate legal, privacy and safety review before launch."}, {"title": "Confidentiality and Safeguarding", "body": "ArtNovaX will take reasonable steps to protect information shared during its activities.\n\nHowever, confidentiality cannot be guaranteed absolutely in group settings or on digital platforms where other participants may access or disclose information.\n\nInformation may be disclosed where required or permitted by law, or where necessary to address a serious safeguarding or safety concern, subject to applicable legal requirements.\n\nRelevant confidentiality limits will be explained before activities where sensitive disclosures may reasonably be expected."}, {"title": "Third-Party Services", "body": "ArtNovaX may use third-party services for registration, communications, surveys, video meetings, data storage or online community features.\n\nSuch providers may process information on ArtNovaX’s behalf or independently under their own terms. ArtNovaX will assess relevant privacy and security risks and put appropriate safeguards in place where required."}, {"title": "Changes and Cancellations", "body": "ArtNovaX may amend, postpone or cancel activities because of safety, operational, funding or other reasonable circumstances.\n\nWhere practicable, registered participants will be notified of significant changes.\n\nAny fees, refunds, cancellation periods or event-specific requirements will be disclosed separately before a participant commits to a paid activity."}, {"title": "Limitation of Liability", "body": "To the extent permitted by Kenyan law, ArtNovaX does not guarantee uninterrupted access to its platforms or any particular outcome from participation.\n\nNothing in these Terms excludes or limits liability where exclusion or limitation is prohibited by law, including applicable obligations relating to personal data protection and participant safety."}, {"title": "Complaints and Dispute Resolution", "body": "Questions, complaints or concerns about our activities or use of personal data may be sent to info@artnovax.org.\n\nArtNovaX will seek to address complaints fairly and promptly.\n\nThese Terms are governed by the laws of Kenya, subject to applicable legal requirements and the jurisdiction of competent courts."}, {"title": "Updates", "body": "We may update these Terms to reflect changes in our activities, technology or legal obligations.\n\nMaterial changes will be communicated where appropriate. Where a change requires fresh consent under applicable law, ArtNovaX will seek that consent."}, {"title": "Contact Details", "body": "Organisation: ArtNovaX Mental Health Foundation\nEmail: info@artnovax.org\nPostal code: 00600\nInquiry contact: +254796454368\n\nThese Terms should be read alongside the ArtNovaX Privacy Notice and any separate consent or programme documents that apply to a participant’s chosen activity."}]}$json$::jsonb,
  null,
  null,
  null
)
on conflict (page_key, section_key)
do update set
  content = excluded.content,
  image = null,
  image_media_id = null,
  image_alt_text = null;
